scripts.progress-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'progress-store',
  description:
    "The language trainer's state: progress, the role-play scene in play, and the review deck of the student's corrections. action:'state' reads it; 'begin' starts a scene; 'reply' records the tutor's line and the errors it found in the student's last message; 'review' grades a review card; 'end' closes the scene; 'advance' moves up a level.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'state', 'begin', 'reply', 'review', 'end', 'advance' (or the older 'status', 'record').",
      required: true,
    },
    scenario: { type: 'string', description: "For begin: a scenario id or title, e.g. 'coffee'." },
    say: { type: 'string', description: "For reply: the tutor's next line, in the language being practiced." },
    errors: {
      type: 'json',
      description: "For reply: mistakes in the student's last message, [{ wrong, right, note? }], at most 3.",
    },
    done: { type: 'boolean', description: "For reply: true when the scene's goal is reached." },
    id: { type: 'string', description: "For review: the review card id, e.g. 'r-3'." },
    verdict: { type: 'string', description: "For review: 'got-it' or 'missed'." },
    note: { type: 'string', description: 'For advance or record: a short note.' },
  },
  outputs: {
    status: { type: 'string', description: "'active' while a scene is in play, else 'idle' (or 'started' / 'done')." },
    display: { type: 'string', description: "For reply: the tutor's line plus the corrections, as shown." },
    level: { type: 'number', description: 'Current level (1+).' },
    streak: { type: 'number', description: 'Days in a row with practice.' },
    dueCount: { type: 'number', description: 'Review cards due now.' },
    message: { type: 'string', description: 'A short summary of the state.' },
    scene: { type: 'json', description: 'The scene in play: title, the part the tutor plays, setting, goal.' },
    dueReviews: { type: 'json', description: 'Up to three corrections due for review, { wrong, right }.' },
    scenarios: { type: 'json', description: 'Scenario ids open at this level (when no scene is in play).' },
    opening: { type: 'boolean', description: 'True right after begin: the tutor opens the scene.' },
  },
  requires: ['workspace.read', 'workspace.write', 'memory.write', 'reminders'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── review-rules-start ──
// Corrections become review cards on three Leitner boxes: box 1 comes back
// the next day, box 2 after three days, box 3 after a week. A card the
// student gets right moves up; a miss, or the same mistake made again in
// conversation, sends it back to box 1. Kept self-contained between these
// sentinels so unit tests execute the shipped bytes.
var REVIEW_INTERVAL_DAYS = { 1: 1, 2: 3, 3: 7 };
var REVIEW_DAY_MS = 24 * 60 * 60 * 1000;

function reviewDueAt(card) {
  if (!card.lastSeenAt) return 0;
  return Date.parse(card.lastSeenAt) + (REVIEW_INTERVAL_DAYS[card.box] || 1) * REVIEW_DAY_MS;
}

function dueReviews(cards, nowMs) {
  return cards
    .filter(function (c) {
      return reviewDueAt(c) <= nowMs;
    })
    .sort(function (a, b) {
      return a.box - b.box || reviewDueAt(a) - reviewDueAt(b);
    });
}

function nextReviewAt(cards, nowMs) {
  var next = Infinity;
  for (var i = 0; i < cards.length; i += 1) {
    var at = reviewDueAt(cards[i]);
    if (at > nowMs && at < next) next = at;
  }
  return next;
}

function cleanText(value, max) {
  return typeof value === 'string' ? value.replace(/\s+/g, ' ').trim().slice(0, max) : '';
}

// The grading the model returned, made safe to store: at most three
// mistakes, each a real change, without duplicates.
function normalizeErrors(raw) {
  var list = Array.isArray(raw) ? raw : [];
  var out = [];
  for (var i = 0; i < list.length && out.length < 3; i += 1) {
    var e = list[i] || {};
    var wrong = cleanText(e.wrong, 80);
    var right = cleanText(e.right, 80);
    if (!wrong || !right || wrong.toLowerCase() === right.toLowerCase()) continue;
    if (out.some(function (o) { return o.wrong.toLowerCase() === wrong.toLowerCase(); })) continue;
    var note = cleanText(e.note, 80);
    out.push(note ? { wrong: wrong, right: right, note: note } : { wrong: wrong, right: right });
  }
  return out;
}

// Each mistake joins the deck, or sends its card back to box 1.
function addCorrections(cards, errors, nowIso) {
  var max = 0;
  for (var i = 0; i < cards.length; i += 1) {
    var m = /^r-(\d+)$/.exec(cards[i].id);
    if (m) max = Math.max(max, Number(m[1]));
  }
  for (var j = 0; j < errors.length; j += 1) {
    var e = errors[j];
    var found = cards.find(function (c) {
      return c.wrong.toLowerCase() === e.wrong.toLowerCase() && c.right.toLowerCase() === e.right.toLowerCase();
    });
    if (found) {
      found.box = 1;
      found.lastSeenAt = nowIso;
      found.repeats = (found.repeats || 0) + 1;
    } else {
      max += 1;
      cards.push({
        id: 'r-' + max,
        wrong: e.wrong,
        right: e.right,
        note: e.note || '',
        box: 1,
        lastSeenAt: nowIso,
        createdAt: nowIso,
        repeats: 0,
      });
    }
  }
  return cards;
}

function gradeReview(card, verdict, nowIso) {
  card.box = verdict === 'got-it' ? Math.min(3, card.box + 1) : 1;
  card.lastSeenAt = nowIso;
  return card;
}

// What the student sees: the tutor's line, then the corrections the app
// recorded, so feedback never depends on the model writing it out.
function displayLine(say, errors, done) {
  var text = say;
  if (errors.length) {
    text +=
      ' — Corrections: ' +
      errors
        .map(function (e) {
          return '"' + e.wrong + '" → "' + e.right + '"' + (e.note ? ' (' + e.note + ')' : '');
        })
        .join('; ') +
      '.';
  }
  if (done) text += ' Scene complete.';
  return text;
}

// The streak counts calendar days with practice, in the device's time zone.
function practiceDay(nowMs) {
  var d = new Date(nowMs);
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}

function nextStreak(streak, lastDay, nowMs) {
  var today = practiceDay(nowMs);
  if (lastDay === today) return streak || 1;
  return lastDay === practiceDay(nowMs - REVIEW_DAY_MS) ? (streak || 0) + 1 : 1;
}
// ── review-rules-end ──

interface Scene {
  id: string;
  title: string;
  role: string;
  setting: string;
  goal: string;
  level: number;
  status: 'active' | 'done';
  turns: number;
  mistakes: number;
  startedAt: string;
}

interface Progress {
  language: string;
  level: number;
  sessions: number;
  streak: number;
  lastPracticeDay: string | null;
  scene: Scene | null;
  history: Array<{ day: string; scene: string; turns: number; mistakes: number }>;
  notes: string[];
}

interface Scenario {
  id: string;
  title: string;
  level: number;
  role: string;
  setting: string;
  goal: string;
}

interface ReviewCard {
  id: string;
  wrong: string;
  right: string;
  note: string;
  box: number;
  lastSeenAt: string | null;
  createdAt: string;
  repeats: number;
}

async function readJson<T>(path: string, fallback: T): Promise<T> {
  try {
    return JSON.parse(await gezel.fs.read(path)) as T;
  } catch {
    return fallback;
  }
}

async function writeJson(path: string, value: unknown): Promise<void> {
  await gezel.fs.write(path, `${JSON.stringify(value, null, 2)}\n`);
}

const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString();
const raw = await readJson<Partial<Progress>>('progress.json', {});
const progress: Progress = {
  language: raw.language ?? 'your language',
  level: raw.level ?? 1,
  sessions: raw.sessions ?? 0,
  streak: raw.streak ?? 0,
  lastPracticeDay: raw.lastPracticeDay ?? null,
  scene: raw.scene ?? null,
  history: Array.isArray(raw.history) ? raw.history : [],
  notes: Array.isArray(raw.notes) ? raw.notes : [],
};
const scenarios = (await readJson<{ scenarios?: Scenario[] }>('scenarios.json', {})).scenarios ?? [];
const deck = await readJson<{ items?: ReviewCard[] }>('reviews.json', {});
const cards: ReviewCard[] = Array.isArray(deck.items) ? deck.items : [];

let status: string = progress.scene?.status === 'active' ? 'active' : 'idle';
let display = '';
let progressChanged = false;
let cardsChanged = false;

function findScenario(query: string): Scenario | undefined {
  const q = query.trim().toLowerCase();
  return (
    scenarios.find((s) => s.id === q) ??
    scenarios.find((s) => s.title.toLowerCase() === q) ??
    scenarios.find((s) => s.title.toLowerCase().includes(q) || q.includes(s.id))
  );
}

function practiced(): void {
  progress.streak = nextStreak(progress.streak, progress.lastPracticeDay, nowMs);
  progress.lastPracticeDay = practiceDay(nowMs);
}

function closeScene(): void {
  const scene = progress.scene;
  if (!scene || scene.status !== 'active') return;
  scene.status = 'done';
  progress.sessions += 1;
  progress.history = [
    ...progress.history,
    { day: practiceDay(nowMs), scene: scene.title, turns: scene.turns, mistakes: scene.mistakes },
  ].slice(-30);
  status = 'done';
}

switch (input.action) {
  case 'begin': {
    const scenario = findScenario(String(input.scenario ?? ''));
    if (!scenario) {
      throw new Error(
        `No scenario '${input.scenario ?? ''}'. Choose one of: ${scenarios.map((s) => s.id).join(', ')}.`,
      );
    }
    progress.scene = {
      id: scenario.id,
      title: scenario.title,
      role: scenario.role,
      setting: scenario.setting,
      goal: scenario.goal,
      level: progress.level,
      status: 'active',
      turns: 0,
      mistakes: 0,
      startedAt: nowIso,
    };
    status = 'started';
    progressChanged = true;
    break;
  }
  case 'reply': {
    const say = String(input.say ?? '').replace(/\s+/g, ' ').trim().slice(0, 240);
    if (!say) throw new Error("reply needs 'say': your next line, in the language being practiced.");
    const errors = normalizeErrors(input.errors);
    if (errors.length) {
      addCorrections(cards, errors, nowIso);
      cardsChanged = true;
      for (const e of errors) {
        const text = `Said "${e.wrong}"; it is "${e.right}"${e.note ? ` (${e.note})` : ''}`.slice(0, 200);
        try {
          await gezel.memory.save(text, { kind: 'correction', scope: 'gezel' });
        } catch {
          // Memory is a bonus; the deck already holds the correction.
        }
      }
    }
    if (progress.scene?.status === 'active') {
      progress.scene.turns += 1;
      progress.scene.mistakes += errors.length;
    }
    practiced();
    // A scene ends once the student has played it: never on the opener, and
    // not before two lines of their own (a small model marked its first line done).
    const finished = input.done === true && (progress.scene?.turns ?? 0) >= 3;
    if (finished) closeScene();
    display = displayLine(say, errors, finished);
    progressChanged = true;
    break;
  }
  case 'review': {
    const card = cards.find((c) => c.id === input.id);
    if (!card || (input.verdict !== 'got-it' && input.verdict !== 'missed'))
      throw new Error("review needs a card 'id' and verdict 'got-it' or 'missed'.");
    gradeReview(card, input.verdict, nowIso);
    cardsChanged = true;
    practiced();
    progressChanged = true;
    break;
  }
  case 'end': {
    closeScene();
    progressChanged = true;
    break;
  }
  case 'advance': {
    progress.level += 1;
    progress.notes = [
      ...progress.notes,
      `Advanced to level ${progress.level}${input.note ? `: ${input.note}` : ''}`,
    ].slice(-20);
    progressChanged = true;
    break;
  }
  case 'record': {
    practiced();
    if (input.note) progress.notes = [...progress.notes, String(input.note)].slice(-20);
    progressChanged = true;
    break;
  }
  case 'state':
  case 'status':
    break;
  default:
    throw new Error(`Unknown action '${input.action}'.`);
}

if (progressChanged) await writeJson('progress.json', progress);
if (cardsChanged) {
  await writeJson('reviews.json', { items: cards });
  // The next card coming due is the one moment a reminder is earned.
  const next = nextReviewAt(cards, nowMs);
  try {
    if (Number.isFinite(next)) {
      const count = dueReviews(cards, next).length;
      await gezel.reminder.set({
        at: new Date(next).toISOString(),
        title: `${progress.language} review`,
        body: `${count} correction${count === 1 ? '' : 's'} ready to practice.`,
      });
    } else await gezel.reminder.clear();
  } catch {
    // A host without reminders still keeps the deck.
  }
}

const due = dueReviews(cards, nowMs);
const scene = progress.scene;
const levelScenes = scenarios.filter((s) => s.level <= progress.level).map((s) => s.id);
gezel.output({
  status,
  display,
  level: progress.level,
  streak: progress.streak,
  dueCount: due.length,
  scene:
    scene && scene.status === 'active'
      ? {
          title: scene.title,
          youPlay: scene.role,
          setting: scene.setting,
          studentGoal: scene.goal,
          turnsSoFar: scene.turns,
        }
      : null,
  opening: status === 'started',
  dueReviews: due.slice(0, 3).map((c) => ({ wrong: c.wrong, right: c.right })),
  scenarios: status === 'idle' ? levelScenes : [],
  message:
    status === 'active' || status === 'started'
      ? `Scene "${scene?.title}": you play the ${scene?.role}. First check the student's last message for mistakes (word gender, verb forms, agreement, word choice) and list each one in errors as { wrong, right }. Then answer in character, only in ${progress.language}.`
      : `Learning ${progress.language}: level ${progress.level}, ${progress.sessions} scene(s), ${progress.streak}-day streak, ${due.length} review(s) due.`,
});
